// Processar e normalizar classificação
const aiResponse = $('IA: Classificar Intenção').item.json.choices[0].message.content.trim();
const message = $('Preparar Entrada').item.json.message;
const context = $('Preparar Entrada').item.json.context;

// Categorias válidas
const validCategories = [
  'INFO_GERAL',
  'SUPORTE_TECNICO',
  'PEDIDO_STATUS',
  'RETENÇÃO',
  'ESCALACAO',
  'OUTRO'
];

// Normalizar resposta
let intent = 'OUTRO';
let confidence = 'medium';

const responseUpper = aiResponse.toUpperCase();

// Buscar categoria correspondente
for (const category of validCategories) {
  if (responseUpper.includes(category)) {
    intent = category;
    // Alta confiança se resposta é exatamente a categoria
    if (responseUpper === category || responseUpper.trim() === category) {
      confidence = 'high';
    } else {
      confidence = 'medium';
    }
    break;
  }
}

// Se não encontrou categoria válida, tentar mapeamento por palavras-chave
if (intent === 'OUTRO' && confidence === 'medium') {
  const messageUpper = message.toUpperCase();

  // Palavras-chave para cada categoria
  const keywordMap = {
    'PEDIDO_STATUS': ['STATUS', 'PEDIDO', 'RASTREAMENTO', 'ENTREGA', 'ONDE ESTÁ'],
    'SUPORTE_TECNICO': ['NÃO FUNCIONA', 'ERRO', 'PROBLEMA', 'BUG', 'FALHA'],
    'RETENÇÃO': ['CANCELAR', 'REEMBOLSO', 'DEVOLVER', 'ARREPENDIMENTO'],
    'ESCALACAO': ['HUMANO', 'SUPERVISOR', 'ATENDENTE', 'FALAR COM', 'PESSOA'],
    'INFO_GERAL': ['HORÁRIO', 'POLÍTICA', 'INFORMAÇÃO', 'COMO FUNCIONA', 'QUAIS SÃO']
  };

  for (const [category, keywords] of Object.entries(keywordMap)) {
    if (keywords.some(keyword => messageUpper.includes(keyword))) {
      intent = category;
      confidence = 'low';
      break;
    }
  }
}

return {
  json: {
    intent: intent,
    confidence: confidence,
    rawResponse: aiResponse,
    message: message,
    context: context,
    classifiedAt: new Date().toISOString(),
    metadata: {
      model: $env.OPENAI_MODEL || 'gpt-4',
      processingTime: 'instant'
    }
  }
};

// Saída formatada para fácil uso
const classification = $('Processar Classificação').item.json;

const output = {
  success: true,
  intent: classification.intent,
  confidence: classification.confidence,
  message: classification.message,
  timestamp: classification.classifiedAt,
  raw: classification
};

return {
  json: output
};
